// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface FeedbackIn {
  /** ExitInterview at the end of the visit; Form from the suggestion box or the desk; KeyInformant in the community */
  channel: "ExitInterview" | "Form" | "KeyInformant";
  respondent: "Patient" | "Relative" | "Anonymous" | "CommunityMember";
  /** Annex A question 1 */
  satisfied: boolean;
  /** Satisfied: from the YES list; not satisfied: from the NO list */
  reasons?: ("CompleteInformation" | "AvailableWhenNeeded" | "NotCostly" | "ConvenientToReach" | "CourteousStaff" | "RelevantStaffAvailable" | "PrivacyObserved" | "FemaleStaffAvailable" | "Recovered" | "Confidentiality" | "Privacy" | "LackOfAttention" | "InadequateInformation" | "AskedToComeAgain" | "Costly" | "LongWait" | "DiscourteousStaff" | "StaffNotCompetent" | "RelevantStaffNotAvailable" | "FemaleStaffNotAvailable" | "SideEffects" | "Other")[];
  /** Required with Other, and only with it */
  other_reason?: string | null;
  comments?: string | null;
  received_on: string;
  /** The visit it is about, when the respondent agrees to be named (GET /opd-queues/reception-dashboard) */
  ticket_id?: number | null;
  /** The patient, when named without a visit; null when anonymous (GET /patients/search) */
  patient_id?: number | null;
}

