/** Record a patient's feedback (Annex A) — POST /api/v1/patient-feedback (who may call: holders of feedback.record or feedback.review). */
export function recordPatientFeedback(body: FeedbackIn): Promise<FeedbackDetailOut> {
  return api<FeedbackDetailOut>("POST", `/patient-feedback`, body, { idempotent: true });
}

/** The blank client satisfaction form (PDF) — GET /api/v1/patient-feedback/form/pdf (who may call: holders of feedback.record or feedback.review). */
export function form(): Promise<unknown> {
  return api<unknown>("GET", `/patient-feedback/form/pdf`, undefined);
}

/** Returning-patient lookup by name / phone / CNIC / UPMRN / MRN — GET /api/v1/patients/search (who may call: holders of patient.search). */
export function searchPatients(query: { q: string; limit?: number }): Promise<PatientSearchHitOut[]> {
  return api<PatientSearchHitOut[]>("GET", withQuery(`/patients/search`, query), undefined);
}

/** All queues, deferred tickets, pending approvals, cash-back prompts — GET /api/v1/opd-queues/reception-dashboard (who may call: holders of opd.queue.view). */
export function receptionDashboard(): Promise<ReceptionDashboardOut> {
  return api<ReceptionDashboardOut>("GET", `/opd-queues/reception-dashboard`, undefined);
}
